<style>.detail-image img{cursor:zoom-in}.afa-detail-zoom{position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,.94);display:none;align-items:center;justify-content:center;padding:20px}.afa-detail-zoom.open{display:flex}.afa-detail-zoom .panel{display:flex;flex-direction:column;align-items:center;gap:12px}.afa-detail-zoom .panel{max-width:96vw;max-height:96vh}.afa-detail-zoom .stage{width:min(90vw,1000px);height:min(76vh,760px);overflow:hidden;position:relative;border:1px solid #b99545;background:#080808;cursor:grab;touch-action:none}.afa-detail-zoom .stage img{position:absolute;max-width:none;max-height:none;width:auto;height:auto;object-fit:initial;transform:none;user-select:none;-webkit-user-drag:none}.afa-detail-zoom .stage.dragging{cursor:grabbing}.afa-detail-zoom button{background:#111;color:#f0d78c;border:1px solid #d8b45d;padding:8px 15px;cursor:pointer}.afa-detail-zoom output{color:#f0d78c;padding:0 10px}</style><div class="afa-detail-zoom" id="afaZoom"><div class="panel"><button id="afaClose">Tutup ✕</button><div class="stage"><img alt="Foto produk diperbesar"></div><div><button id="afaMinus">−</button><output>100%</output><button id="afaPlus">+</button><button id="afaReset">Reset</button></div></div></div><script>(function(){const im=document.querySelector('.detail-image img'),v=document.getElementById('afaZoom'),stage=v.querySelector('.stage'),big=stage.querySelector('img'),o=v.querySelector('output');let z=1,x=0,y=0,drag=false,sx=0,sy=0,ox=0,oy=0;function apply(){const r=stage.getBoundingClientRect(),w=big.naturalWidth||700,h=big.naturalHeight||700,s=Math.min(r.width/w,r.height/h),ww=w*s*z,hh=h*s*z;x=ww<r.width?(r.width-ww)/2:Math.min(0,Math.max(r.width-ww,x));y=hh<r.height?(r.height-hh)/2:Math.min(0,Math.max(r.height-hh,y));big.style.width=ww+'px';big.style.height=hh+'px';big.style.left=x+'px';big.style.top=y+'px';o.textContent=Math.round(z*100)+'%'}if(im&&!im.hidden)im.addEventListener('click',()=>{big.onload=()=>{z=1;x=y=0;apply()};big.src=im.currentSrc||im.src;v.classList.add('open')});document.getElementById('afaClose').onclick=()=>v.classList.remove('open');document.getElementById('afaMinus').onclick=()=>{z=Math.max(1,z/1.35);apply()};document.getElementById('afaPlus').onclick=()=>{z=Math.min(12,z*1.35);apply()};document.getElementById('afaReset').onclick=()=>{z=1;x=y=0;apply()};stage.addEventListener('wheel',e=>{e.preventDefault();z=e.deltaY<0?Math.min(12,z*1.18):Math.max(1,z/1.18);apply()},{passive:false});stage.addEventListener('pointerdown',e=>{drag=true;sx=e.clientX;sy=e.clientY;ox=x;oy=y;stage.classList.add('dragging');stage.setPointerCapture(e.pointerId)});stage.addEventListener('pointermove',e=>{if(drag){x=ox+e.clientX-sx;y=oy+e.clientY-sy;apply()}});['pointerup','pointercancel'].forEach(ev=>stage.addEventListener(ev,()=>{drag=false;stage.classList.remove('dragging')}));v.addEventListener('click',e=>{if(e.target===v)v.classList.remove('open')});document.addEventListener('keydown',e=>{if(e.key==='Escape')v.classList.remove('open')});window.addEventListener('resize',()=>{if(v.classList.contains('open'))apply()})})();</script><script src="/assets/js/pwa-register.js"></script></body></html>